<script setup>
import {ref,shallowRef,onBeforeUnmount,watch,nextTick,onMounted} from 'vue';
import {Button,Field,Cell,Popup,Picker} from 'vant';import 'vant/es/button/style';import 'vant/es/field/style';import 'vant/es/cell/style';import 'vant/es/popup/style';import 'vant/es/picker/style';
import StudentCorrectionPad from './StudentCorrectionPad.vue';import StudentGradedAnswer from './StudentGradedAnswer.vue';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=shallowRef(controller.snapshot()),a=controller.actions,picker=ref(false),historyCell=ref(),tabs=ref(),transcription=ref(false),studyFrame=ref();
const unsubscribe=controller.subscribe(value=>m.value=value);let resizeObserver;
onBeforeUnmount(()=>{unsubscribe();resizeObserver?.disconnect();});
const verdict=v=>({correct:'正确',partial:'部分正确',incorrect:'需要订正',unanswered:'未作答',review:'待人工核对'})[v]||'待批改';
const originalId='photo-original-'+Math.random().toString(36).slice(2),knowledgeId='photo-knowledge-'+Math.random().toString(36).slice(2);
function centerTab(){const root=tabs.value,button=root?.querySelector('[aria-current=page]');if(!root||!button)return;const r=root.getBoundingClientRect(),b=button.getBoundingClientRect();root.scrollLeft+=b.left+b.width/2-r.left-root.clientLeft-root.clientWidth/2;}
watch(()=>m.value.question?.id,()=>nextTick(centerTab));watch(tabs,(value,old)=>{if(old)resizeObserver?.unobserve(old);if(value)resizeObserver?.observe(value);nextTick(centerTab);});onMounted(()=>{if(typeof ResizeObserver==='function'){resizeObserver=new ResizeObserver(centerTab);if(tabs.value)resizeObserver.observe(tabs.value);}});
function choose({selectedValues}){a.selectGrade(selectedValues[0]);picker.value=false;nextTick(()=>historyCell.value?.$el?.focus({preventScroll:true}));}
function regionStyle(region){if(![region.x,region.y,region.width,region.height].every(Number.isFinite)||region.x<0||region.y<0||region.width<=0||region.height<=0||region.x+region.width>1.00001||region.y+region.height>1.00001)return {display:'none'};return {left:region.x*100+'%',top:region.y*100+'%',width:region.width*100+'%',height:region.height*100+'%'};}
</script>
<template><section v-if="m.visible" class="student-photo-review"><header class="photo-review-header"><h2>逐题批改</h2><Button icon="cross" aria-label="关闭逐题工作台" :disabled="m.busy||m.importing" @click="a.close"/></header><p v-if="m.paper?.warnings?.length" class="photo-warning">{{m.paper.warnings.join('；')}}</p><nav v-if="m.paper&&!m.inline" ref="tabs" class="photo-question-tabs" aria-label="切换题目"><Button v-for="q in m.paper.questions" :key="q.id" :disabled="m.busy||m.importing" :type="q.id===m.question?.id?'primary':'default'" :aria-current="q.id===m.question?.id?'page':undefined" @click="a.switchQuestion(q.id)">第 {{q.number||'?'}} 题 · {{verdict(q.grades?.at(-1)?.result?.verdict)}}</Button></nav><p v-if="!m.question" role="status">{{m.status||'正在打开题目…'}}</p><template v-else><div class="photo-review-heading"><h3 :class="{'photo-wrong':m.wrong}">第 {{m.question.number}} 题</h3><Button :aria-expanded="m.sourceOpen" :aria-controls="originalId" @click="a.source(!m.sourceOpen)">{{m.sourceOpen?'收起原题':'查看原题'}}</Button></div><div class="photo-review-layout" :class="{'has-source':m.sourceOpen}"><section v-if="m.sourceOpen" :id="originalId" class="photo-review-source"><h3>原始作业</h3><div class="photo-actions"><Button v-for="page in m.paper.pages||[]" :key="page.page" :type="m.sourcePage===page.page?'primary':'default'" @click="a.sourcePage(page.page)">第 {{page.page}} 页</Button></div><div v-if="m.source" class="photo-original-page"><img :src="m.source.image" :alt="'第 '+m.sourcePage+' 页作业原图'"/><span v-for="(region,i) in m.sourceRegions" :key="i" class="photo-region" :style="regionStyle(region)" aria-hidden="true"/></div><p v-else class="photo-warning">该来源页没有保存原图，请补回原稿；题目和批改记录仍保留。</p></section><section class="photo-review-main"><template v-if="!m.inline"><div class="math-prose" :class="{'photo-wrong':m.wrong}" v-html="m.questionHtml"/><div class="photo-diagrams"><template v-for="(diagram,i) in m.diagrams" :key="i"><div v-if="diagram.svg" v-html="diagram.svg"/><img v-else-if="diagram.image" :src="diagram.image" :alt="'第 '+m.question.number+' 题插图'"/></template></div></template><p v-if="m.question.uncertain?.length" class="photo-warning">识别疑点：{{m.question.uncertain.join('；')}}</p><p v-if="m.stale" class="photo-warning">题干已修改，下方记录对应旧版本。请提交新作答后再追问。</p>
 <template v-if="m.grade"><p class="photo-verdict">{{verdict(m.grade.result.verdict)}}</p><Button :aria-expanded="m.knowledgeOpen" :aria-controls="knowledgeId" @click="a.knowledge(!m.knowledgeOpen)">关联知识点</Button><section v-if="m.knowledgeOpen" :id="knowledgeId" class="photo-knowledge"><template v-for="role in ['gap','tested']" :key="role"><h4 v-if="m.grade.result.knowledge?.some(k=>k.role===role)">{{role==='gap'?'错误反映的薄弱点':'本题考查的知识点'}}</h4><article v-for="(link,i) in (m.grade.result.knowledge||[]).filter(k=>k.role===role)" :key="role+':'+i"><Button tag="a" :href="link.href" @click.prevent="a.study(link.href)">{{link.title}}</Button><div class="math-prose" v-html="m.render(link.reason)"/></article></template><h4 v-if="m.grade.result.models?.length">几何模型匹配</h4><article v-for="(link,i) in m.grade.result.models||[]" :key="'model:'+i"><Button tag="a" :href="link.href" @click.prevent="a.study(link.href)">{{link.modelId}}号 · {{link.title}}</Button><div class="math-prose" v-html="m.render(link.reason)"/></article><p v-if="!m.grade.result.knowledge?.length&&!m.grade.result.models?.length">尚无已可靠关联的知识点。</p></section>
 <section v-if="m.canFollowup" class="photo-followup"><h4>围绕这次批改追问</h4><div class="photo-actions"><Button v-for="prompt in ['这一步为什么错','只提示下一步','换一种讲法']" :key="prompt" :disabled="m.locked" @click="a.followup(prompt)">{{prompt}}</Button></div><article v-if="m.latestFollowup" class="photo-latest-followup"><p><strong>我：</strong>{{m.latestFollowup.prompt}}</p><div class="math-prose" v-html="m.render(m.latestFollowup.reply)"/></article><Field :model-value="m.draft.prompt||''" label="我的追问" type="textarea" autosize rows="2" maxlength="1600" :disabled="m.locked" @update:model-value="a.prompt"/><Button type="primary" :disabled="m.locked" @click="a.followup(m.draft.prompt)">发送追问</Button></section>
 <Cell ref="historyCell" class="photo-history-select" title="查看批改记录" :value="(m.grade.kind==='initial'?'首次原稿批改':'订正批改')+' · '+verdict(m.grade.result.verdict)" is-link :clickable="!m.busy&&!m.importing" @click="!m.busy&&!m.importing&&(picker=true)"/><StudentGradedAnswer :key="m.question.id" :grade="m.grade" :question="m.question" :paper="m.paper" :render="m.render"/>
 </template><p v-else>该题尚无逐题批改。解答题可在下方上传本次完整作答照片。</p><section v-if="m.canCorrect" class="photo-correction"><Button :aria-expanded="m.draft.correctionOpen??!m.grade" :disabled="m.locked" @click="a.correction(!(m.draft.correctionOpen??!m.grade))">订正后再练 · 保留首次批改</Button><div v-if="m.draft.correctionOpen??!m.grade"><StudentCorrectionPad :key="m.question.id" :controller="controller" :model="m"/><Button type="primary" :disabled="m.locked" :loading="m.busy" @click="a.submit">提交本次作答批改</Button></div></section><p v-else-if="m.question.questionType!=='written'" class="photo-type-note">{{m.question.questionType==='choice'||m.question.questionType==='fill'?'选择题、填空题不提供 AI批改。':'本题题型尚未核对，确认是解答题后可提交 AI批改。'}}</p><div class="photo-actions"><Button v-if="m.busy" @click="a.cancel">取消请求</Button><Button v-if="m.dirty" :disabled="m.busy||m.importing||m.blocked" @click="a.save">保存原稿草稿</Button></div><p role="status" aria-live="polite" class="photo-review-status">{{m.status}}</p></section></div></template>
 <Popup v-model:show="picker" position="bottom" round class="photo-review-picker"><header class="photo-review-header"><h2>查看批改记录</h2><Button icon="cross" aria-label="关闭批改记录选择" @click="picker=false"/></header><Picker :model-value="[m.selectedGrade]" :columns="(m.question?.grades||[]).map((g,i)=>({text:(g.kind==='initial'?'首次原稿批改':'订正批改 '+i)+' · '+verdict(g.result.verdict),value:g.id}))" @confirm="choose"><template #cancel><Button icon="cross" aria-label="关闭批改记录选择" @click="picker=false"/></template></Picker></Popup><Popup :show="!!m.study" @update:show="value=>!value&&a.closeStudy()" position="bottom" class="photo-study-popup"><header class="photo-review-header"><h2>知识点与模型复习</h2><Button icon="cross" aria-label="关闭关联复习" @click="a.closeStudy"/></header><iframe v-if="m.study" ref="studyFrame" :src="m.study" @load="a.attachStudyFrame(studyFrame?.contentWindow)" title="关联课程复习"/></Popup></section></template>
<style scoped>
.student-photo-review{--van-primary-color:#22634b;--van-button-primary-background:#22634b;--van-button-primary-border-color:#22634b;color:#26372e;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;padding:18px 0;min-width:0;overflow-wrap:anywhere}.student-photo-review,.student-photo-review.student-photo-review :deep(*){box-sizing:border-box}.photo-review-header,.photo-review-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:12px 0}.photo-review-header h2{font-size:19px;margin:0}.photo-review-header :deep(.van-button){width:44px;padding:0}.student-photo-review.student-photo-review :deep(.van-button){min-height:44px;font:inherit;text-decoration:none;max-width:100%}.student-photo-review.student-photo-review :deep(.van-button__text){white-space:normal;overflow-wrap:anywhere}.student-photo-review.student-photo-review :deep(.van-field__control){background:transparent;border:0;box-shadow:none;min-height:0;padding:0;font:inherit}.student-photo-review.student-photo-review :deep(.van-cell){background:transparent;padding:14px 0}.student-photo-review.student-photo-review :deep(.van-field__label){width:75px}.photo-question-tabs{display:flex;gap:8px;overflow:auto;scrollbar-width:thin;padding:6px 0 14px;max-width:100%}.photo-question-tabs :deep(.van-button){flex:0 0 auto}.photo-question-tabs :deep(.van-button--primary){background:#22634b;color:#fff;border-color:#22634b}.photo-review-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:22px}.photo-review-layout.has-source{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.photo-review-main,.photo-review-source{min-width:0}.photo-review-heading h3{font-size:18px;margin:0}.math-prose{line-height:1.9;white-space:pre-wrap;min-width:0;overflow-wrap:anywhere}.math-prose :deep(.katex-display){overflow-x:auto;overflow-y:hidden;max-width:100%}.photo-diagrams{display:flex;flex-wrap:wrap;gap:12px}.photo-diagrams>div{max-width:100%;min-width:0}.photo-diagrams :deep(svg),.photo-diagrams img{max-width:100%;height:auto}.photo-wrong{color:#b42318}.photo-verdict{font-size:20px;font-weight:650}.photo-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0}.photo-knowledge,.photo-followup,.photo-correction{margin:18px 0;line-height:1.9}.photo-knowledge h4,.photo-followup h4{font-size:16px}.photo-knowledge article{margin-bottom:14px}.photo-latest-followup{color:#b42318;font-weight:600}.photo-history-select{border-top:1px solid #dce4dc;margin-top:22px}.photo-original-page{position:relative;max-width:100%;line-height:0}.photo-original-page img{display:block;width:100%;height:auto}.photo-region{position:absolute;border:2px dashed #b42318;pointer-events:none}.photo-warning,.photo-review-status{font-size:14px;line-height:1.8;color:#9a3529}.photo-type-note{font-size:14px;color:#66766a}.photo-review-picker{color:#26372e}.photo-review-picker .photo-review-header{padding:8px 18px}.photo-review-picker :deep(.van-button){height:44px;min-height:44px}.photo-review-picker :deep(.van-picker__confirm){min-height:44px}.photo-study-popup{width:100%;height:94dvh;display:flex;flex-direction:column;color:#26372e}.photo-study-popup .photo-review-header{padding:8px 18px}.photo-study-popup iframe{border:0;width:100%;flex:1;min-height:0}@media(max-width:760px){.photo-review-layout.has-source{grid-template-columns:minmax(0,1fr)}.photo-review-source{order:0}.photo-review-main{order:1}}@media(prefers-reduced-motion:reduce){.student-photo-review.student-photo-review :deep(*){animation:none!important;transition:none!important}}
</style>

