ius:8px;text-align:left;color:#263c30;background:#fff}.photo-history-select :deep(.van-cell__right-icon){position:absolute;right:10px;bottom:10px}.photo-correction{margin-top:24px}.photo-knowledge h4,.photo-followup h4{font-size:1em}.photo-warning,.photo-review-status{font:inherit}.photo-latest-followup{font-weight:700}
